import {initializeApp} from "firebase/app";
import {getFirestore,connectFirestoreEmulator,getDoc,doc} from "firebase/firestore";
const app=initializeApp({projectId:"demo-reading-club"});
const db=getFirestore(app);connectFirestoreEmulator(db,"127.0.0.1",8080);
const snapshot=await getDoc(doc(db,"books","moon-trip"));
console.log(snapshot.exists()?snapshot.data().title:"No book at this path");
